// high-level example
ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
defer cancel()
stream, err := client.OpenStream(ctx)
if err != nil { return err }
// if user explicitly presses cancel button:
stream.CancelIntent(ctx, "user-abort")
// on transport failure, attempt automatic resume:
ok, err := stream.AttemptResume(ctx)
if ok { // resume succeeded }
